#[cfg(target_arch="wasm32")]use wasm_bindgen::prelude::*;use crate::session::{PendingInteraction,Session};
fn esc(s:&str)->String{s.replace('\\',"\\\\").replace('"',"\\\"").replace('\n',"\\n")}fn arr(xs:&[String])->String{format!("[{}]",xs.iter().map(|x|format!("\"{}\"",esc(x))).collect::<Vec<_>>().join(","))}fn pending_json(p:PendingInteraction)->String{match p{PendingInteraction::Investigate{name,options,cost,budget}=>format!("{{\"kind\":\"investigate\",\"name\":\"{}\",\"options\":{},\"cost\":{},\"budget\":{}}}",esc(&name),arr(&options),cost,budget),PendingInteraction::Choice{name,options,budget}=>format!("{{\"kind\":\"choice\",\"name\":\"{}\",\"options\":{},\"budget\":{}}}",esc(&name),arr(&options),budget),PendingInteraction::Complete=>"{\"kind\":\"complete\"}".into()}}
#[cfg_attr(target_arch="wasm32",wasm_bindgen)]pub fn evaluate_summary(source:&str)->String{match crate::parser::parse(source).and_then(|p|crate::eval::evaluate(&p)){Ok(e)=>format!("CAVEAT|nodes={}|edges={}|events={}",e.graph.nodes.len(),e.graph.edges.len(),e.history.len()),Err(e)=>format!("CAVEAT_ERROR|{e}")}}
#[cfg_attr(target_arch="wasm32",wasm_bindgen)]pub struct WebSession{inner:Session}
#[cfg_attr(target_arch="wasm32",wasm_bindgen)]impl WebSession{#[cfg_attr(target_arch="wasm32",wasm_bindgen(constructor))]pub fn new(source:&str)->Result<WebSession,String>{Ok(Self{inner:Session::from_source(source)?})}pub fn pending(&self)->String{match self.inner.pending(){Ok(p)=>pending_json(p),Err(e)=>format!("{{\"kind\":\"error\",\"message\":\"{}\"}}",esc(&e))}}pub fn apply(&mut self,selection:&str)->Result<(),String>{self.inner.apply(selection)}pub fn discoveries(&self)->String{format!("[{}]",self.inner.discoveries().iter().map(|d|format!("{{\"because\":\"{}\",\"evidence\":\"{}\",\"relation\":\"{}\",\"target\":\"{}\"}}",esc(&d.because),esc(&d.evidence),esc(&d.relation),esc(&d.target))).collect::<Vec<_>>().join(","))}pub fn summary(&self)->String{match crate::eval::evaluate(self.inner.program()){Ok(e)=>{let b=e.resources.as_ref().map(|x|format!("{}/{}",x.remaining,x.initial)).unwrap_or_else(||"none".into());format!("CAVEAT|nodes={}|edges={}|events={}|budget={}",e.graph.nodes.len(),e.graph.edges.len(),e.history.len(),b)},Err(e)=>format!("CAVEAT_ERROR|{e}")}}}
